from typing import Final

import pytest

DEFAULTS: Final[dict[str, str]] = {"mode": "fast", "level": "3"}


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay keys[i] -> values[i] on DEFAULTS and return the resulting values.

    Output order: mode, level, then any other keys in the order first given.
    Setting a key that is already present replaces its value.
    """
    merged: dict[str, str] = dict(DEFAULTS)
    for key, value in zip(keys, values, strict=True):
        merged[key] = value
    return list(merged.values())


def test_defaults_when_no_overrides() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_default_mode() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_default_level() -> None:
    assert settings(["level"], ["5"]) == ["fast", "5"]


def test_override_both_defaults() -> None:
    assert settings(["level", "mode"], ["1", "safe"]) == ["safe", "1"]


def test_extra_key_appended_after_defaults() -> None:
    assert settings(["color"], ["red"]) == ["fast", "3", "red"]


def test_extra_keys_keep_given_order() -> None:
    assert settings(["z", "a"], ["1", "2"]) == ["fast", "3", "1", "2"]


def test_mixed_defaults_and_extras() -> None:
    assert settings(["color", "mode"], ["red", "slow"]) == ["slow", "3", "red"]


def test_repeated_extra_key_last_value_wins() -> None:
    assert settings(["x", "x"], ["1", "2"]) == ["fast", "3", "2"]
